// NODE 1: INPUT VALIDATION - Parse input_json string from backend
// Handles input from Nexus backend with JSON strings that need parsing

const body = $input.first().json.body || $input.first().json;

// Helper to parse JSON strings
function parseJSON(value, fieldName) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (e) {
      throw new Error(`Invalid ${fieldName} JSON format: ${e.message}`);
    }
  }
  return null;
}

// Parse project_details JSON string
const projectDetails = parseJSON(body.project_details, 'project_details') || {};

// Parse input_json JSON string (THIS WAS THE ISSUE!)
const inputJson = parseJSON(body.input_json, 'input_json') || {};
const resolvedLabels = inputJson.resolvedLabels || {};
const behaviours = inputJson.behaviours || [];

// Map program_type to target_level
function mapProgramTypeToLevel(programType) {
  const map = {
    'young_leaders_development': 'Mid',
    'senior_leadership': 'High',
    'executive': 'Exceptional',
    'first_time_managers': 'Low'
  };
  return map[programType] || 'Mid';
}

// Extract required fields
const referenceUrl = inputJson.reference_case_url || resolvedLabels['Reference Case URL'] || '';
const clientName = body.client_name || projectDetails.name?.split('|')[0]?.trim() || '';
const industry = projectDetails.industry || '';
const targetLevel = mapProgramTypeToLevel(projectDetails.program_type);

// Validate required fields
const missing = [];
if (!referenceUrl) missing.push('reference_case_url');
if (!clientName) missing.push('client_name');
if (!industry) missing.push('industry');
if (!behaviours || behaviours.length === 0) missing.push('behaviours');

if (missing.length > 0) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: `Missing required fields: ${missing.join(', ')}`,
      missing_fields: missing,
      debug_info: {
        has_input_json: !!inputJson,
        has_project_details: !!projectDetails,
        behaviours_count: behaviours.length,
        input_json_type: typeof body.input_json,
        reference_url_sources: {
          from_inputJson: inputJson.reference_case_url || null,
          from_resolvedLabels: resolvedLabels['Reference Case URL'] || null
        }
      }
    }
  }];
}

// Validate reference URL format
if (!referenceUrl.match(/^https:\/\/(drive|docs)\.google\.com\//)) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: 'Invalid Google Drive URL format',
      received_url: referenceUrl
    }
  }];
}

// Validate behaviors count
if (behaviours.length < 2 || behaviours.length > 15) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: 'Behaviours count must be between 2 and 15',
      received: behaviours.length
    }
  }];
}

// Extract additional fields
const creationDetails = inputJson.creationDetails || {};
const typeSpecificInputs = inputJson.typeSpecificInputs || {};

// Parse CSV fields
function parseCSV(str) {
  if (!str) return [];
  return str.split(',').map(s => s.trim()).filter(Boolean);
}

// All validations passed - return 3 core objects
return [{
  json: {
    status: 'validated',
    google_drive_file_url: referenceUrl,
    // Core Object 1: Will be populated after extraction
    reference_case_text: null,
    // Core Object 2: case_study_context (normalized from input)
    case_study_context: {
      // Required fields
      client_name: clientName,
      industry: industry,
      target_level: targetLevel,
      business_function: creationDetails.businessFunction || resolvedLabels['Business Function'] || '',

      // Behaviors (convert from array to expected format)
      behaviors: behaviours.map(b => ({
        name: b.name,
        definition: b.definition || ''
      })),

      // Project memory
      project_memory: body.current_project_memory || '',

      // Creation config
      creation_mode: inputJson.creationMode || resolvedLabels['Creation Mode'] || '',
      base_case_study_name: inputJson.selectedBaseCaseStudy?.title || resolvedLabels['Base Case Study'] || '',
      change_scope: typeSpecificInputs.changeScope || resolvedLabels['Change Scope'] || 'industry_context_only',

      // Narrative settings
      narrative_arc: parseCSV(resolvedLabels['Narrative Arc']) || creationDetails.narrativeArc || [],
      tension_patterns: parseCSV(resolvedLabels['Tension Patterns']) || creationDetails.tensionPatterns || [],
      decision_types: parseCSV(resolvedLabels['Decision Types']) || creationDetails.decisionTypes || [],
      decision_complexity: creationDetails.decisionComplexity || resolvedLabels['Decision Complexity'] || 'medium_managerial',
      tone: creationDetails.tone || resolvedLabels['Tone'] || 'professional_business',
      must_include: parseCSV(resolvedLabels['Must Include']) || creationDetails.mustInclude || [],

      // Case study settings
      challenge_approach: typeSpecificInputs.challengeApproach || resolvedLabels['Challenge Approach'] || 'combined',
      case_study_length: typeSpecificInputs.lengthPreference || resolvedLabels['Case Study Length'] || 'standard',
      number_of_questions: parseInt(typeSpecificInputs.questionsPerChallenge || resolvedLabels['Questions per Challenge']) || 5,
      hide_behaviors_in_questions: (typeSpecificInputs.questionsMustNotMentionBehaviors === true) || (resolvedLabels['Hide Behaviors in Questions'] === 'Yes'),

      // Workflow identifiers
      workflow_session_id: body.workflow_session_id || `session_${Date.now()}`,
      workflow_id: body.workflow_id || 'case_study_modification',
      project_id: body.project_id || '',
      client_id: body.client_id || ''
    },
    // Core Object 3: Will accumulate generated content
    generated_case: {}
  }
}];

// Validate extraction and output 3 core objects
const subWorkflowResult = $input.first().json;
const originalInput = $('1.2_VAL_Input').first().json;

const validationErrors = [];

if (subWorkflowResult.status !== 'ok') {
  validationErrors.push(`Sub-workflow status is "${subWorkflowResult.status}", expected "ok"`);
}

if (Array.isArray(subWorkflowResult.errors) && subWorkflowResult.errors.length > 0) {
  validationErrors.push(`Sub-workflow returned errors: ${JSON.stringify(subWorkflowResult.errors)}`);
}

if (!subWorkflowResult.data || typeof subWorkflowResult.data !== 'object') {
  validationErrors.push('Sub-workflow data object is missing or invalid');
}

const extractedText = subWorkflowResult.data?.extracted_text;
if (!extractedText || typeof extractedText !== 'string' || extractedText.trim() === '') {
  validationErrors.push('Extracted text is missing or empty');
}

const charCount = subWorkflowResult.data?.char_count || 0;
if (charCount < 100) {
  validationErrors.push(`Extracted text too short (${charCount} chars)`);
}

if (validationErrors.length > 0) {
  return [{
    json: {
      status: 'extraction_failed',
      error_type: 'extraction_validation_error',
      error_message: validationErrors.join(' | '),
      validation_errors: validationErrors,
      sub_workflow_output: subWorkflowResult
    }
  }];
}

// Return 3 core objects with populated reference_case_text
return [{
  json: {
    status: 'extraction_validated',
    // Core Object 1: Extracted text
    reference_case_text: extractedText,
    // Core Object 2: User context (unchanged)
    case_study_context: originalInput.case_study_context,
    // Core Object 3: Empty, will be filled by LLM nodes
    generated_case: {},
    // Metadata
    extraction_metadata: {
      source_url: subWorkflowResult.data.source_url,
      mimeType: subWorkflowResult.data.mimeType,
      file_name: subWorkflowResult.data.file_name,
      extraction_method: subWorkflowResult.data.extraction_method,
      char_count: charCount
    }
  }
}];

// FORMAT Node 2: Build context analysis prompt
const input = $input.first().json;
const ctx = input.case_study_context;

const behaviorNames = (ctx.behaviors || []).map(b => b.name).join(', ');
const behaviorCount = (ctx.behaviors || []).length;

const prompt = `You are a case study design architect. Generate design constraints for a behavioral assessment case study.

INPUTS:
- Client: ${ctx.client_name} | Industry: ${ctx.industry} | Level: ${ctx.target_level}
- Function: ${ctx.business_function} | Complexity: ${ctx.decision_complexity}
- Behaviors (${behaviorCount}): ${behaviorNames}
- Narrative Arc: ${(ctx.narrative_arc || []).join(', ')}
- Tension Patterns: ${(ctx.tension_patterns || []).join(', ')}
- Decision Types: ${(ctx.decision_types || []).join(', ')}
- Challenge Approach: ${ctx.challenge_approach}
- Case Study Length: ${ctx.case_study_length}
- Total Questions: ${ctx.number_of_questions}
- Change Scope: ${ctx.change_scope}
- Must Include: ${(ctx.must_include || []).join(', ')}

PROJECT CONTEXT (from Focus Group Discussions):
${ctx.project_memory || 'No project memory provided'}

TASKS:

1. Determine challenge count:
   - 2-3 behaviors per challenge (from challenge_approach)
   - Total challenges = ceil(behavior_count / 3), capped at 2-4
   - 100% behavior coverage, no repeats

2. Distribute behaviors across challenges:
   - Group naturally complementary behaviors
   - Use FGD insights to inform grouping (e.g., if FGD highlights "reactive planning", pair planning-related behaviors together)

3. Distribute questions across challenges:
   - Total: ${ctx.number_of_questions}
   - Spread across challenges proportionally
   - Each question tests 2-3 behaviors from its challenge

4. Set difficulty using target_level:
   | Level | Decision Complexity | Language | Ambiguity | Stakeholders |
   | Low | Simple | Simple, accessible | Low | Direct team |
   | Mid | Moderate trade-offs | Simple, professional | Moderate | Team + peers |
   | High | Multi-variable | Professional, strategic | High | Cross-functional |
   | Exceptional | Systemic | Executive | Very high | Org-wide + external |

5. Generate word limits dictionary:
   {
     "situation": 130,
     "introduction_overview": 60,
     "introduction_market": 60,
     "introduction_initiative": 40,
     "introduction_team_targets": 40,
     "per_challenge": 200,
     "conclusion": 60,
     "per_question": 40
   }

6. Extract 2-3 FGD integration points from project_memory:
   Format: [{"element": "string", "integration_suggestion": "how to weave this in"}]

7. Select 2-3 scenario styles from:
   Crisis management | Strategic transformation | Operational efficiency | Team dynamics |
   Cross-functional collaboration | Resource constraints | Market pressure |
   Innovation adoption | Regulatory challenges

RULES:
- Default language difficulty to SIMPLE unless target_level is High/Exceptional
- Short sentences throughout
- Present continuous or past tense only

Return JSON only:
{
  "design_constraints": {
    "number_of_challenges": number,
    "behavior_distribution": {
      "challenge_1": { "behaviors": ["name1", "name2"] },
      "challenge_2": { "behaviors": ["name3", "name4"] }
    },
    "question_distribution": {
      "challenge_1": number,
      "challenge_2": number
    },
    "scenario_styles": ["style1", "style2"],
    "fgd_integration_points": [
      { "theme": "string", "how_to_use": "string" }
    ],
    "difficulty": {
      "decision_complexity": "string",
      "language": "string",
      "ambiguity": "string",
      "stakeholder_complexity": "string"
    },
    "word_limits": {
      "situation": 130,
      "introduction_overview": 60,
      "introduction_market": 60,
      "introduction_initiative": 40,
      "introduction_team_targets": 40,
      "per_challenge": 200,
      "conclusion": 60,
      "per_question": 40
    }
  }
}
`;

return [{ json: {
  prompt: prompt,
  model: 'global.anthropic.claude-sonnet-4-5-20250929-v1:0',
  node_name: 'Node2_Context',
  workflow_session_id: ctx.workflow_session_id,
  workflow_id: ctx.workflow_id,
  project_id: ctx.project_id,
  client_id: ctx.client_id
}}];

// MERGE Node 2: Add design_constraints to case_study_context
const llmResult = $input.first().json;
const coreObjects = $('1.6_VAL_Extraction').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 2 LLM response missing');
}

// Add design_constraints to existing case_study_context
return [{
  json: {
    reference_case_text: coreObjects.reference_case_text,
    case_study_context: {
      ...coreObjects.case_study_context,
      case_design_constraints: llmResult.llm_response.design_constraints || llmResult.llm_response
    },
    generated_case: coreObjects.generated_case,
    extraction_metadata: coreObjects.extraction_metadata
  }
}];

// FORMAT Node 3: Build reference parsing prompt
const input = $input.first().json;
const ctx = input.case_study_context;
const refText = input.reference_case_text || '';

const prompt = `Extract the structure and content elements from this reference case study.

REFERENCE TEXT:
${refText}

CHANGE SCOPE: ${ctx.change_scope || 'industry_context_only'}

Extract:
1. Section structure (what sections exist, their order)
2. For each section: key content elements (characters, company details, metrics, scenarios)
3. Writing style (sentence length, tense, person, vocabulary level)
4. Challenge structure (how many, what narrative beats each uses)
5. How challenges interconnect (shared characters, cascading consequences)

**Protagonist Details:**
- Extract protagonist name and role
- Note seniority level implied

**Quantitative Data with Context:**
- For each data point: {value: "string", context: "where/how it's used"}
- Flag whether essential for decision or decorative

**Table Relevance Flagging:**
- For each table: {description: "string", essential: boolean}
- Essential = needed for answering questions
- Decorative = adds color but not required

Return JSON only:
{
  "parsed_reference": {
    "sections": [
      { "name": "string", "word_count": number, "key_elements": ["string"] }
    ],
    "protagonist_name": "string",
    "protagonist_role": "string",
    "characters": [
      { "name": "string", "role": "string", "appears_in": ["section_name"] }
    ],
    "company": {
      "name": "string",
      "industry": "string",
      "products": ["string"],
      "competitors": ["string"]
    },
    "metrics": ["string"],
    "quantitative_data": [{"value": "string", "context": "string"}],
    "tables": [{"description": "string", "essential": true}],
    "challenge_structure": {
      "count": number,
      "interconnections": ["string"]
    },
    "style": {
      "avg_sentence_length": "short|medium|long",
      "tense": "string",
      "person": "string"
    }
  }
}
`;

return [{ json: {
  prompt: prompt,
  model: 'global.anthropic.claude-sonnet-4-5-20250929-v1:0',
  node_name: 'Node3_ParseRef',
  workflow_session_id: ctx.workflow_session_id,
  workflow_id: ctx.workflow_id,
  project_id: ctx.project_id,
  client_id: ctx.client_id
}}];

// MERGE Node 3: Add parsed_reference to generated_case
const llmResult = $input.first().json;
const prev = $('2.3_MRG_Context').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 3 LLM response missing');
}

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      parsed_reference: llmResult.llm_response.parsed_reference || llmResult.llm_response
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// FORMAT Node 4: Build industry adaptation prompt
const input = $input.first().json;
const ctx = input.case_study_context;
const genCase = input.generated_case;
const parsedRef = genCase.parsed_reference || {};

const prompt = `Transform the reference case study elements to fit the target industry.

REFERENCE:
- Company: ${parsedRef.company?.name || 'Unknown'} (${parsedRef.company?.industry || 'Unknown'})
- Characters: ${(parsedRef.characters || []).map(c => `${c.name} (${c.role})`).join(', ')}
- Products: ${(parsedRef.company?.products || []).join(', ')}
- Competitors: ${(parsedRef.company?.competitors || []).join(', ')}
- Metrics: ${(parsedRef.metrics || []).join(', ')}

TARGET:
- Client: ${ctx.client_name} | Industry: ${ctx.industry} | Function: ${ctx.business_function}
- Change Scope: ${ctx.change_scope}

RULES:
- Replace company name, products, competitors, and metrics with ${ctx.industry}-authentic equivalents
- All names, brands, data must be fictional
- Designations and products must exist in the target industry/region
- If change_scope is "Change only industry context": preserve narrative structure, character dynamics, and challenge flow — only swap industry-specific elements

### Industry Terms - Parenthetical Explanations (MANDATORY)
For any industry-specific term that might be unfamiliar:
- Add brief parenthetical explanation
- Example: "CAR (Corrective Action Request)" or "EBITDA margins (earnings before interest, tax, depreciation, amortization)"
- Keep explanations to 3-7 words

### Protagonist Name Adaptation
- If original name seems culturally mismatched for ${ctx.client_name}'s region, adapt
- Ensure name matches geographic/cultural context
- Keep original if already appropriate

## QUALITY CHECK BEFORE OUTPUT
□ Every paragraph authentically reflects ${ctx.industry}?
□ No leftover references to original industry/company?
□ Strategic context points feel naturally integrated?
□ Someone from ${ctx.client_name} would recognize this as realistic?
□ Word counts haven't bloated significantly?

Return JSON only:
{
  "industry_adapted": {
    "company_name": "string (fictional)",
    "industry_context": "string (one line)",
    "products_services": ["string"],
    "competitors": [
      { "name": "string", "positioning": "string" }
    ],
    "characters": [
      { "original_name": "string", "new_name": "string", "role": "string" }
    ],
    "metrics": [
      { "original": "string", "adapted": "string" }
    ],
    "regional_notes": "string (if any region-specific adjustments)"
  }
}
`;

return [{ json: {
  prompt: prompt,
  model: 'global.anthropic.claude-sonnet-4-5-20250929-v1:0',
  node_name: 'Node4_Industry',
  workflow_session_id: ctx.workflow_session_id,
  workflow_id: ctx.workflow_id,
  project_id: ctx.project_id,
  client_id: ctx.client_id
}}];

// MERGE Node 4: Add industry_adapted to generated_case
const llmResult = $input.first().json;
const prev = $('3.3_MRG_ParseRef').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 4 LLM response missing');
}

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      industry_adapted: llmResult.llm_response.industry_adapted || llmResult.llm_response
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// FORMAT Node 5: Build behavior mapping prompt
const input = $input.first().json;
const ctx = input.case_study_context;
const genCase = input.generated_case;
const constraints = ctx.case_design_constraints || ctx.design_constraints || {};
const industryAdapted = genCase.industry_adapted || {};

const behaviorsWithDef = (ctx.behaviors || []).map(b => `- ${b.name}: ${b.definition}`).join('\n');

const prompt = `Create challenge outlines and map questions to behaviors.

BEHAVIOR DISTRIBUTION:
${JSON.stringify(constraints.behavior_distribution, null, 2)}

QUESTION DISTRIBUTION:
${JSON.stringify(constraints.question_distribution, null, 2)}

BEHAVIORS (with definitions):
${behaviorsWithDef}

INDUSTRY CONTEXT: ${industryAdapted.company_name} — ${industryAdapted.industry_context}
SCENARIO STYLES: ${(constraints.scenario_styles || []).join(', ')}
FGD POINTS: ${JSON.stringify(constraints.fgd_integration_points || [], null, 2)}
TENSION PATTERNS: ${(ctx.tension_patterns || []).join(', ')}
DECISION TYPES: ${(ctx.decision_types || []).join(', ')}
NARRATIVE ARC: ${(ctx.narrative_arc || []).join(', ')}

For each challenge, create:
1. A thematic title (e.g., "Navigating Complexity", "Building Capability")
2. A scenario outline (2-3 sentences: triggering event, core tension, what's at stake)
3. Which FGD point it integrates
4. Which tension patterns and decision types it uses

**B. BEHAVIOR STITCHING STORYLINE**
This is CRITICAL. Show how ALL behaviors in this challenge connect into ONE coherent scenario:
- How will Behavior 1 manifest? (What goes wrong because of its absence?)
- How will Behavior 2 manifest? (What consequence shows the need?)
- How will Behavior 3 manifest? (What situation demands it?)
- How do these behaviors INTERCONNECT in the same situation?

RULE: Behaviors must be WOVEN together, not presented as separate mini-problems.

**C. EVIDENCE MOMENTS**
For each behavior, list 2-3 specific moments in a participant's response where the behavior could be demonstrated. These become the "behavior surface area" for assessment.

**D. MANDATORY ELEMENTS PLANNING**
Plan how this challenge will include:
- Quantitative metrics/data
- Cause-effect relationships
- Human/people implications
- Business implications

**E. DIFFICULTY CALIBRATION**
Based on ambiguity_level and stakeholder_complexity:
- What information will be deliberately unclear?
- Which stakeholders will have competing interests?
- What interconnection exists with other challenges?

For each question, specify:
1. Which challenge it belongs to
2. Which 2-3 behaviors it tests
3. A one-line focus (what the question should probe)

RULES:
- Every behavior appears in exactly one challenge
- Every behavior is tested by at least one question
- Challenges must interconnect (shared characters or cascading consequences)
- At least one challenge must include the reader's own leadership failure
- At least one challenge must have a strategic decision point

Return JSON only:
{
  "behavior_mapping": {
    "challenges": [
      {
        "number": 1,
        "title": "string",
        "behaviors": ["name1", "name2"],
        "scenario_outline": "string",
        "behavior_stitching_storyline": "string",
        "evidence_moments": [{"behavior": "name", "moments": ["string", "string"]}],
        "mandatory_elements_plan": {"metrics": "string", "cause_effect": "string", "human_implications": "string"},
        "fgd_point": "string",
        "tension": "string",
        "decision_type": "string",
        "reader_failure": true,
        "strategic_decision": true,
        "interconnection": "string",
        "red_herring_elements": ["string"]
      }
    ],
    "questions": [
      {
        "number": 1,
        "challenge_number": 1,
        "behaviors_tested": ["name1", "name2"],
        "focus": "string"
      }
    ]
  }
}
`;

return [{ json: {
  prompt: prompt,
  model: 'global.anthropic.claude-sonnet-4-5-20250929-v1:0',
  node_name: 'Node5_Behavior',
  workflow_session_id: ctx.workflow_session_id,
  workflow_id: ctx.workflow_id,
  project_id: ctx.project_id,
  client_id: ctx.client_id
}}];

// MERGE Node 5: Add challenge_outlines to generated_case (V3 - simplified)
const llmResult = $input.first().json;
const prev = $('4.3_MRG_Industry').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 5 LLM response missing');
}

const response = llmResult.llm_response;

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      behavior_mapping: { challenge_outlines: response.challenge_outlines || [] }
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// MERGE Node 6a: Add situation and introduction to generated_case
const llmResult = $input.first().json;
const prev = $('5.3_MRG_Behavior').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 6a LLM response missing');
}

const response = llmResult.llm_response;

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      situation: response.situation || '',
      introduction: response.introduction || {}
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// FORMAT Node 6b: Build prompt for challenge writing
const input = $input.first().json;
const ctx = input.case_study_context;
const genCase = input.generated_case;

const constraints = ctx.case_design_constraints || ctx.design_constraints || {};
const industryAdapted = genCase.industry_adapted || genCase.industry_adapted_case || {};
const behaviorMapping = genCase.behavior_mapping || {};
const situation = genCase.situation || '';
const introduction = genCase.introduction || {};
const challengeOutlines = behaviorMapping.challenge_outlines || behaviorMapping.challenges || [];

const wordLimits = constraints.word_limits || { per_challenge: 200 };

// Concatenate introduction sub-sections
const introText = [
  introduction.company_overview,
  introduction.market_context,
  introduction.strategic_initiative,
  introduction.team_and_targets
].filter(Boolean).join('\n\n');

const prompt = `You are a case study writer. Write the challenge blocks. The Situation and Introduction are already written — continue the narrative.

## SITUATION (for continuity)
${situation}

## INTRODUCTION (for continuity)
${introText}

## CHALLENGE OUTLINES
${JSON.stringify(challengeOutlines, null, 2)}

## CHARACTERS
${JSON.stringify(industryAdapted.characters || [], null, 2)}

## COMPETITORS
${JSON.stringify(industryAdapted.competitors || [], null, 2)}

## METRICS
