    workflow_session_id: ctx.workflow_session_id,
    workflow_id: ctx.workflow_id,
    project_id: ctx.project_id,
    client_id: ctx.client_id,
    case_design_constraints: constraints
  },
  case_study_content: {
    situation: situation,
    introduction: introObj,
    legacy_introduction: [situation, formattedIntro, conclusion].filter(Boolean).join('\n\n').trim(),
    challenges: enhancedChallenges,
    conclusion: conclusion
  },
  assessment_questions: questions,
  assessor_guidance: assessorGuidance,
  quality_summary: {
    overall_rating: Math.round(overallRating * 10) / 10,
    average_rating: Math.round(avgRating * 10) / 10,
    total_checks_passed: passedChecks,
    total_checks_conducted: 16,
    passed_quality_check: overallRating >= 8,
    passed_bias_check: passedBias,
    total_behaviors_covered: behaviorsList.length,
    unique_behaviors: behaviorsList.length,
    behaviors_list: behaviorsList,
    behavior_coverage_analysis: {
      coverage_percentage: '100%',
      distribution: distribution
    },
    recommendations_for_deployment: recommendations
  }
};

return [{
  json: {
    status: 'success',
    final_output: final_output,
    // Keep generated_case as internal trace
    generated_case: genCase,
    reference_case_text: prev.reference_case_text,
    extraction_metadata: prev.extraction_metadata,
    delivery_ready: true
  }
}];

// ERROR Response - Safely serialize error objects
const input = $input.first().json;

// Helper to safely extract error information
function safeErrorExtract(error) {
  if (!error) return null;

  // If it's an Error object, extract its properties safely
  if (error instanceof Error || error.message) {
    return {
      message: error.message || 'Unknown error',
      name: error.name,
      stack: error.stack,
      code: error.code,
      // Extract any additional enumerable properties
      ...Object.keys(error).reduce((acc, key) => {
        try {
          acc[key] = error[key];
        } catch (e) {
          // Skip read-only properties
        }
        return acc;
      }, {})
    };
  }

  // If it's already a plain object, return as-is
  return error;
}

const errorInfo = safeErrorExtract(input);

return [{
  json: {
    status: 'error',
    message: errorInfo?.message || input?.error_message || 'Workflow execution failed',
    error_type: input?.error_type || 'execution_error',
    error_details: errorInfo,
    node_name: $node.name,
    timestamp: new Date().toISOString()
  }
}];
